#!/usr/bin/env python3
"""Implement the compiler described in the task instructions."""
import json
import sys


def compile_bundle(request):
    """Return the canonical DFA and query results, or a specified error."""
    raise NotImplementedError('Implement policy compilation')


def main():
    for line in sys.stdin.buffer:
        request = json.loads(line)
        print(json.dumps(compile_bundle(request)), flush=True)


if __name__ == '__main__':
    main()

