"""Independent reference: semantic evaluation + naive DFA construction."""
import json
from collections import deque


def ref_eval(expr, w):
    op = expr["op"]
    if op == "true":
        return True
    if op == "false":
        return False
    p = list(expr["path"]) if "path" in expr else None
    if op == "match":
        return list(w) == p
    if op == "startswith":
        m = len(p)
        return len(w) >= m and list(w[:m]) == p
    if op == "endswith":
        m = len(p)
        return len(w) >= m and list(w[len(w) - m:]) == p
    if op == "contains":
        m = len(p)
        if m == 0:
            return True
        for i in range(len(w) - m + 1):
            if list(w[i:i + m]) == p:
                return True
        return False
    if op == "not":
        return not ref_eval(expr["arg"], w)
    if op == "and":
        return all(ref_eval(a, w) for a in expr["args"])
    if op == "or":
        return any(ref_eval(a, w) for a in expr["args"])
    raise AssertionError(op)


def ref_accept(rules, w):
    allowed = False
    dropped = False
    for r in rules:
        v = ref_eval(r["when"], w)
        if r["action"] == "allow":
            allowed = allowed or v
        else:
            dropped = dropped or v
    return allowed and not dropped


# ---- monitor built directly from the prose definition ----

def monitor_step(op, p, k, a):
    """Next monitor state from state k after reading token a (pattern p)."""
    m = len(p)
    if op == "match" or op == "startswith":
        if k < m:
            return k + 1 if a == p[k] else m + 1
        if k == m:
            return m if op == "startswith" else m + 1
        return m + 1
    if op == "contains" and k == m:
        return m
    # endswith (and contains while k < m): largest j <= m with p[:j] suffix of p[:k]+[a]
    word = list(p[:k]) + [a]
    for j in range(min(m, k + 1), -1, -1):
        if list(word[len(word) - j:]) == list(p[:j]):
            return j
    raise AssertionError


def monitor_states(op, p, w):
    """All monitor states visited, ending with the state after w."""
    k = 0
    for a in w:
        k = monitor_step(op, p, k, a)
    return k


def build_monitor_states(op, p, alphabet):
    """Enumerate reachable monitor states and transitions by simulation."""
    m = len(p)
    nst = m + 2 if op in ("match", "startswith") else m + 1
    trans = [[monitor_step(op, p, s, a) for a in alphabet] for s in range(nst)]
    return trans, m


def build_product_ref(atoms, alphabet):
    monitors = []
    finals = []
    for op, p in atoms:
        t, m = build_monitor_states(op, p, alphabet)
        monitors.append(t)
        finals.append(m)
    init = tuple([0] * len(monitors))
    index = {init: 0}
    states = [init]
    trans = []
    i = 0
    while i < len(states):
        cur = states[i]
        row = []
        for si in range(alphabet):
            nxt = tuple(monitors[j][cur[j]][si] for j in range(len(monitors)))
            if nxt not in index:
                index[nxt] = len(states)
                states.append(nxt)
            row.append(index[nxt])
        trans.append(row)
        i += 1
    return states, trans, finals


def naive_minimize(n, k, trans, accept):
    cls = [1 if accept[s] else 0 for s in range(n)]
    while True:
        sig = {}
        new = [0] * n
        for s in range(n):
            key = (accept[s], tuple([cls[t] for t in trans[s]]))
            if key not in sig:
                sig[key] = len(sig)
            new[s] = sig[key]
        if len(sig) == len(set(cls)):
            return new
        cls = new


def ref_compile(obj):
    services = obj["services"]
    rules = obj["rules"]
    queries = obj["queries"]
    alphabet = len(services)
    atoms = []
    seen = set()
    for r in rules:
        stack = [r["when"]]
        while stack:
            e = stack.pop()
            op = e["op"]
            if op in ("match", "startswith", "endswith", "contains"):
                key = (op, tuple(e["path"]))
                if key not in seen:
                    seen.add(key)
                    atoms.append(key)
            elif op == "not":
                stack.append(e["arg"])
            else:
                stack.extend(e["args"])
    states, trans, finals = build_product_ref(atoms, alphabet)
    n = len(states)
    accept = []
    for st in states:
        tv = tuple(st[i] == finals[i] for i in range(len(atoms)))
        accept.append(ref_accept(rules_tv(rules, atoms, tv), []))
    # the above is awkward; evaluate directly:
    accept = []
    for st in states:
        tv = tuple(st[i] == finals[i] for i in range(len(atoms)))
        accept.append(eval_with_tv(rules, atoms, tv))
    cls = naive_minimize(n, alphabet, trans, accept)
    rep = {}
    for s in range(n):
        if cls[s] not in rep:
            rep[cls[s]] = s
    ctrans = {c: [cls[t] for t in trans[rep[c]]] for c in rep}
    cacc = {c: accept[rep[c]] for c in rep}
    start = cls[0]
    numbering = {start: 0}
    order = deque([start])
    rows = []
    accs = []
    while order:
        c = order.popleft()
        row = []
        for t in ctrans[c]:
            if t not in numbering:
                numbering[t] = len(numbering)
                order.append(t)
            row.append(numbering[t])
        rows.append(row)
        accs.append(cacc[c])
    total = len(rows)
    dist = [None] * total
    rev = [[] for _ in range(total)]
    for s in range(total):
        for t in rows[s]:
            rev[t].append(s)
    q = deque()
    for s in range(total):
        if accs[s]:
            dist[s] = 0
            q.append(s)
    while q:
        u = q.popleft()
        for v in rev[u]:
            if dist[v] is None:
                dist[v] = dist[u] + 1
                q.append(v)
    sidx = {s: i for i, s in enumerate(services)}
    out_q = []
    for path in queries:
        s = 0
        for tok in path:
            s = rows[s][sidx[tok]]
        out_q.append({"state": s, "allow": accs[s], "distance": dist[s]})
    return {
        "ok": True,
        "dfa": {"start": 0, "accept": accs, "next": rows, "distance": dist},
        "queries": out_q,
    }


def rules_tv(rules, atoms, tv):
    raise NotImplementedError


def eval_with_tv(rules, atoms, tv):
    amap = {a: i for i, a in enumerate(atoms)}

    def ev(e):
        op = e["op"]
        if op == "true":
            return True
        if op == "false":
            return False
        if op in ("match", "startswith", "endswith", "contains"):
            return tv[amap[(op, tuple(e["path"]))]]
        if op == "not":
            return not ev(e["arg"])
        if op == "and":
            return all(ev(a) for a in e["args"])
        return any(ev(a) for a in e["args"])

    allowed = False
    dropped = False
    for r in rules:
        v = ev(r["when"])
        if r["action"] == "allow":
            allowed = allowed or v
        else:
            dropped = dropped or v
    return allowed and not dropped
